/** 바이크 매물 v11(2026-10-10 「바이크도 500개 보강」): 사용자 구글 시트 「가상 매물 시나리오 › 바이크 신규」 500행(라이트바겐 공개 목록 수집본)을 옮긴 값.
 *  제조사·모델·연식·주행·가격·배기량·서류·게시일·인증중고 여부는 시트 그대로, 장르·면허·변속기는 모델 기준으로 정한 값, 연료는 전부 가솔린.
 *  지역은 시트의 시도에 구·군을 돌려 붙인 값(시트에 구·군이 없음, 「용산점」은 서울 용산구), 가격이 빈 7대는 같은 제조사 중간값, 게시일이 빈 26대는 1~3일 전.
 *  판매자는 시트에 없어 개인·업체를 정한 값(인증중고 26대 = 인증 판매업체, 나머지 3대 중 1대 = 전문 판매업체)이고 이름은 가상이다.
 *  원본 상세 URL·매물 ID는 저장하지 않는다. 사진은 public/assets/bike/listings/v11/(thumb = 목록 썸네일 사본, 글자는 인식해서 흐림 처리).
 *  사진이 매물 사진이 아닌 19장(계기판·부품·서류·확대 사진)은 같은 모델(없으면 같은 제조사)의 다른 매물 사진으로 대신한다(image_action). */
